import os
import re
import sys

def _safe_rel(path, root):
    try:
        return os.path.relpath(path, root)
    except Exception:
        return path

def _snippet_for(path, terms, context_lines):
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as fh:
            lines = fh.read().splitlines()
    except Exception:
        return None
    lower_terms = [term.lower() for term in terms]
    best = None
    best_score = -1
    for idx, line in enumerate(lines):
        low = line.lower()
        score = sum(1 for term in lower_terms if term in low)
        if score > best_score:
            best_score = score
            best = idx
    if best is None:
        return None
    start = max(0, best - context_lines)
    end = min(len(lines), best + context_lines + 1)
    return chr(10).join('{:4d}: {}'.format(i + 1, lines[i]) for i in range(start, end))

def main():
    try:
        request = json.load(sys.stdin)
    except Exception:
        request = {}
    root = request.get('root') or '/testbed'
    query = request.get('query') or ''
    if not isinstance(query, str):
        query = ', '.join(str(item) for item in query)
