            'details': {'root': root, 'terms': terms},
        }
        print(json.dumps(result))
        return
    lower_terms = [term.lower() for term in terms]
    scored = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in ('.git', '.hg', '.svn', '__pycache__', '.tox', '.venv', 'node_modules')]
        dirnames.sort()
        filenames.sort()
        for fname in filenames:
            if not fname.endswith('.py'):
                continue
            path = os.path.join(dirpath, fname)
            try:
                if os.stat(path).st_size > 2000000:
                    continue
                with open(path, 'r', encoding='utf-8', errors='replace') as fh:
                    text = fh.read()
            except Exception:
                continue
            lower_text = text.lower()
            counts = {}
            total = 0
            for term in lower_terms:
                n = lower_text.count(term)
                if n:
                    counts[term] = n
                    total += n
            if total:
                scored.append((total, len(counts), path, counts))
    scored.sort(key=lambda item: (-item[0], -item[1], item[2].lower()))
    top = scored[:max_results]
    lines = ['Query terms: ' + ', '.join(terms)]
    lines.append('Matches: {} file(s); showing {}'.format(len(scored), len(top)))
