        'terms': terms,
        'total_matched_files': len(scored),
        'files': [
            {
                'path': _safe_rel(path, root),
                'hits': total,
                'matched_terms': term_count,
                'term_counts': counts,
            }
            for total, term_count, path, counts in top
        ],
        'snippets': snippets,
    }
    print(json.dumps({'content': content, 'details': details}))

if __name__ == '__main__':
    main()
